const phone=document.querySelector('.phone');
function fit(){document.documentElement.style.setProperty('--scale',Math.min(window.innerWidth/750,.5));}
fit();window.addEventListener('resize',fit);
const markets=[['道琼斯','38554.80','−0.36%',51,334,false],['英国富时','10804.80','+0.26%',289,333,true],['日经225','65269.33','−0.17%',548,333,false],['纳斯达克','26506.80','+1.92%',129,449,true],['创业板指','3359.80','+0.20%',338,449,true],['上证指数','3960.80','+0.27%',485,449,true],['标普500','7718.80','−0.38%',51,564,false],['深证成指','13703.80','+1.92%',289,568,true],['恒生指数','25317.80','−0.10%',548,564,false]];
const indices=document.querySelector('#indices');
function renderMarkets(){indices.replaceChildren(...markets.map(([name,value,change,x,y,up])=>{const el=document.createElement('div');el.className='market-index';el.style.left=x+'px';el.style.top=y+'px';el.innerHTML=`<div class="label">${name}</div><div class="value ${up?'up':'down'}">${value}</div><div class="change ${up?'up':'down'}">${change}</div>`;return el;}));}
renderMarkets();
let toastTimer;function toast(text){const el=document.querySelector('.toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
const sheet=document.querySelector('.sheet');function openSheet(title,content){document.querySelector('#sheet-title').textContent=title;const target=document.querySelector('#sheet-content');target.replaceChildren();if(typeof content==='string'){const p=document.createElement('p');p.textContent=content;target.append(p);}else target.append(content);sheet.showModal();}
document.querySelector('.close-sheet').onclick=()=>sheet.close();sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)sheet.close();}});
document.querySelector('.menu').onclick=()=>openSheet('财小通','行情日报 · 自选追踪 · 深度思考 · 金融技能');
document.querySelector('.mini-app').onclick=()=>openSheet('关于页面','财小通行情首页设计预览。页面展示原稿中的示例行情。');
document.querySelector('.play').onclick=function(){const active=this.getAttribute('aria-pressed')!=='true';this.setAttribute('aria-pressed',String(active));this.setAttribute('aria-label',active?'暂停行情日报':'播放行情日报');if('speechSynthesis' in window){speechSynthesis.cancel();if(active){const speech=new SpeechSynthesisUtterance('行情日报。'+markets.map(x=>x[0]+x[1]+',涨跌幅'+x[2]).join('。'));speech.lang='zh-CN';speech.onend=()=>{this.setAttribute('aria-pressed','false');this.setAttribute('aria-label','播放行情日报');};speechSynthesis.speak(speech);}}else toast('当前浏览器不支持语音播报');};
document.querySelector('.next-index').onclick=()=>{markets.push(markets.shift());const positions=[[51,334],[289,333],[548,333],[129,449],[338,449],[485,449],[51,564],[289,568],[548,564]];markets.forEach((m,i)=>{m[3]=positions[i][0];m[4]=positions[i][1];});renderMarkets();};
document.querySelector('#all-sectors').onclick=()=>{const list=document.createElement('div');document.querySelectorAll('.sector').forEach(el=>{const row=document.createElement('div');row.className='sheet-row';row.textContent=el.textContent;list.append(row);});openSheet('热门板块',list);};
document.querySelectorAll('.sector').forEach(el=>el.onclick=()=>openSheet(el.querySelector('span').textContent,'板块涨跌幅 '+el.querySelector('strong').textContent+'。此为原稿中的示例数据。'));
document.querySelector('.manage').onclick=function(){const active=phone.classList.toggle('editing');this.querySelector('span').textContent=active?'完成':'管理';document.querySelectorAll('.stock-card,.compact-stock').forEach(el=>el.draggable=active);if(active)toast('拖动卡片可调整自选顺序');};
let dragged;document.querySelectorAll('.stock-card,.compact-stock').forEach(el=>{el.addEventListener('dragstart',()=>{dragged=el;el.classList.add('dragging');});el.addEventListener('dragend',()=>{el.classList.remove('dragging');dragged=null;});el.addEventListener('dragover',e=>{if(dragged&&dragged.parentElement===el.parentElement)e.preventDefault();});el.addEventListener('drop',e=>{e.preventDefault();if(dragged&&dragged!==el&&dragged.parentElement===el.parentElement)el.before(dragged);});});
document.querySelector('#thinking').onclick=function(){const on=this.getAttribute('aria-pressed')!=='true';this.setAttribute('aria-pressed',String(on));toast(on?'已开启深度思考':'已关闭深度思考');};
document.querySelector('#skills').onclick=()=>openSheet('金融技能','支持行情解读、行业观察、自选追踪与投资知识学习。');
document.querySelector('.voice').onclick=()=>toast('请使用输入框输入消息');
document.querySelector('.message-box').onsubmit=e=>{e.preventDefault();const input=e.currentTarget.querySelector('input');const message=input.value.trim();if(!message){input.focus();return;}openSheet('消息预览',message+'\n\n此页面为设计还原预览，尚未接入问答服务。');input.value='';};
